// Test Data: datasets generated by the Test Data Intelligence Agent and linked to TFS test cases.

import { api } from "../api.js";
import { esc, toast, dateTimeOf } from "../util.js";

async function render(view, filters = {}) {
  const q = new URLSearchParams();
  if (filters.test_case_id) q.set("test_case_id", filters.test_case_id);
  if (filters.user_story_id) q.set("user_story_id", filters.user_story_id);
  const { items } = await api(`/api/test-data?${q}`);
  view.querySelector("#list").innerHTML = items.length ? `
    <table class="data"><thead><tr><th>Test Case</th><th>User Story</th><th>Dataset</th><th>Kind</th><th>Values</th><th>Updated</th><th></th></tr></thead><tbody>
    ${items.map((d) => `<tr data-id="${d.id}"><td>${d.tfs_test_case_id ? `<a href="#/test-cases?id=${d.tfs_test_case_id}">#${d.tfs_test_case_id}</a>` : esc(d.test_case_ref)}</td>
      <td>${d.user_story_id ? `<a href="#/user-stories?id=${esc(d.user_story_id)}">#${esc(d.user_story_id)}</a>` : ""}</td>
      <td>${esc(d.name)}</td><td>${esc(d.kind || "")}</td><td><code>${esc(JSON.stringify(d.dataset))}</code></td><td>${esc(dateTimeOf(d.updated_at))}</td>
      <td><button class="link-btn" data-edit="${d.id}">Edit</button> · <button class="link-btn" data-del="${d.id}">Delete</button>
        ${d.tfs_test_case_id ? ` · <button class="link-btn" data-tfs="${d.tfs_test_case_id}" title="Write all data sets of this test case into its Summary and Parameter values in TFS">Write to TFS</button>` : ""}</td></tr>`).join("")}
    </tbody></table>`
    : '<p class="muted">No test data yet. Datasets appear here after you generate a test design and save its test cases to TFS.</p>';
  view.querySelectorAll("[data-edit]").forEach((b) => b.addEventListener("click", async () => {
    const row = items.find((x) => String(x.id) === b.dataset.edit);
    const text = prompt(`Edit values for "${row.name}" (JSON)`, JSON.stringify(row.dataset, null, 2));
    if (text === null) return;
    try {
      await api(`/api/test-data/${row.id}`, { method: "PATCH", body: { values: JSON.parse(text) } });
      toast("Test data saved", "success");
      render(view, filters);
    } catch (err) { toast(err instanceof SyntaxError ? "That is not valid JSON." : err.message, "error"); }
  }));
  view.querySelectorAll("[data-tfs]").forEach((b) => b.addEventListener("click", async () => {
    b.disabled = true;
    try {
      const r = await api(`/api/test-data/tfs/${b.dataset.tfs}`, { method: "POST", body: {} });
      toast(`Test Case #${r.test_case_id} updated in TFS with ${r.datasets} data set(s)`, "success");
    } catch (err) { toast(err.message, "error"); }
    b.disabled = false;
  }));
  view.querySelectorAll("[data-del]").forEach((b) => b.addEventListener("click", async () => {
    if (!confirm("Delete this dataset?")) return;
    try { await api(`/api/test-data/${b.dataset.del}`, { method: "DELETE" }); render(view, filters); }
    catch (err) { toast(err.message, "error"); }
  }));
}

export async function mount(view) {
  view.innerHTML = `
    <form class="card row" id="f" style="margin-bottom:12px">
      <input name="test_case_id" placeholder="Test case ID" inputmode="numeric">
      <input name="user_story_id" placeholder="User story ID" inputmode="numeric">
      <button class="btn" type="submit">Filter</button>
    </form>
    <div class="card" id="list"><p class="muted">Loading…</p></div>`;
  view.querySelector("#f").addEventListener("submit", (e) => {
    e.preventDefault();
    const f = new FormData(e.target);
    render(view, { test_case_id: f.get("test_case_id"), user_story_id: f.get("user_story_id") });
  });
  await render(view);
}
